        jdbc.update("""
                        INSERT INTO restriction_list (operator_id, reason, start_date, end_date, active)
                        VALUES (?, ?, ?, ?, 1)
                        """,
                operatorId, reason, Date.valueOf(startDate), Date.valueOf(endDate));
    }
}

