                rs.getDate("issue_date").toLocalDate(),
                rs.getDate("expire_date").toLocalDate(),
                rs.getDate("harvest_date") == null ? null : rs.getDate("harvest_date").toLocalDate(),
                rs.getDate("void_date") == null ? null : rs.getDate("void_date").toLocalDate());
