    public void insert(LicensePO po) {
        jdbc.update("""
                        INSERT INTO harvest_license
                            (id, application_id, operator_id, subplot_id, species_code, quota_year, volume,
                             status, issue_date, expire_date, harvest_date, void_date)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
