     * 首次处理失败：删除 PENDING 占位，使同键后续请求可重新校验（失败不缓存）。
     */
    public void deletePending(IdempotentOperation operation, String requestId) {
        jdbc.update("""
                        DELETE FROM idempotent_request
                         WHERE operation = ? AND request_id = ? AND status = 'PENDING'
                        """,
                operation.name(), requestId);
    }
}

